#[test] fn adv60(){let mut spur_unsat=vec![];let mut mism=vec![];for &(name,s,z3) in CASES{let l=run(s,false);let h=run(s,true);if l=="sat"&&z3=="unsat"||h=="sat"&&z3=="unsat"{ /* oxiz too weak vs z3 unsat: spurious SAT, not dangerous here */ }if (z3=="sat")&&(l=="unsat"||h=="unsat"){spur_unsat.push(format!("{name} legacy={l} hooks={h} z3={z3}"));}if l!=z3||h!=z3{mism.push(format!("{name} legacy={l} hooks={h} z3={z3}"));}}
println!("total={} mismatches={} SPURIOUS_UNSAT={}",CASES.len(),mism.len(),spur_unsat.len());
for m in &mism{println!("  MISMATCH {m}");}
assert!(spur_unsat.is_empty(),"SPURIOUS UNSAT (dangerous): {:?}",spur_unsat);}